const std = @import("std");
const lex = @import("lexer.zig");
pub const Text = lex.Text;
pub const Position = struct { file: Text, line: i64 };
pub const Macro = struct {
    name: Text, parameters: ?[]const Text = null, variadic: bool = false, replacement: []lex.Token, position: Position, main: bool, expanded: usize = 0, tested: usize = 0,
    pub fn parameter(m: *const Macro, name: Text) ?usize { const ps = m.parameters orelse return null; for (ps, 0..) |p, i| if (lex.eq(p, name)) return i; return null; }
    pub fn signature(m: *const Macro, a: std.mem.Allocator) !Text {
        if (m.parameters == null) return m.name; var text: std.ArrayList(u8) = .empty; try text.appendSlice(a, m.name); try text.append(a, '(');
        for (m.parameters.?, 0..) |p, i| { if (i > 0) try text.appendSlice(a, ", "); try text.appendSlice(a, if (m.variadic and i + 1 == m.parameters.?.len) "..." else p); }
        try text.append(a, ')'); return text.items;
    }
};
pub fn builtin(name: Text) bool { return lex.eq(name, "__LINE__") or lex.eq(name, "__FILE__") or lex.eq(name, "__COUNTER__"); }
pub fn nameError(a: std.mem.Allocator, tokens: []const lex.Token, directive: Text) !?Text {
    if (tokens.len == 0) return try std.fmt.allocPrint(a, "no macro name given in #{s} directive", .{directive}); if (tokens[0].kind != .identifier) return "macro names must be identifiers";
    const name = tokens[0].spelling; if (lex.eq(name, "defined")) return "\"defined\" cannot be used as a macro name";
    if (builtin(name)) return try std.fmt.allocPrint(a, "cannot {s} builtin macro \"{s}\"", .{if (lex.eq(directive, "define")) "redefine" else "undefine", name}); return null;
}
pub const Parsed = union(enum) { macro: *Macro, message: Text };
const va_error = "\"__VA_ARGS__\" can only appear in the expansion of a variadic macro";
pub fn parse(a: std.mem.Allocator, tokens: []const lex.Token, position: Position, main: bool) !Parsed {
    if (try nameError(a, tokens, "define")) |message| return .{ .message = message };
    const name = tokens[0].spelling; if (lex.eq(name, "__VA_ARGS__")) return .{ .message = va_error };
    var index: usize = 1; var params: ?[]const Text = null; var variadic = false;
    if (tokens.len > 1 and lex.eq(tokens[1].spelling, "(") and !tokens[1].space) {
        index = 2; var list: std.ArrayList(Text) = .empty;
        if (index == tokens.len) return .{ .message = "missing ')' in macro parameter list" };
        if (!lex.eq(tokens[index].spelling, ")")) while (true) {
            if (index == tokens.len) return .{ .message = "missing ')' in macro parameter list" }; const t = tokens[index]; index += 1;
            if (lex.eq(t.spelling, "...")) { variadic = true; try list.append(a, "__VA_ARGS__"); }
            else if (t.kind == .identifier) { if (lex.eq(t.spelling, "__VA_ARGS__")) return .{ .message = va_error }; for (list.items) |p| if (lex.eq(p, t.spelling)) return .{ .message = try std.fmt.allocPrint(a, "duplicate macro parameter \"{s}\"", .{p}) }; try list.append(a, t.spelling); }
            else return .{ .message = try std.fmt.allocPrint(a, "expected parameter name, found \"{s}\"", .{t.spelling}) };
            if (index == tokens.len) return .{ .message = "missing ')' in macro parameter list" };
            const next = tokens[index].spelling; if (lex.eq(next, ")")) break;
            if (variadic) return .{ .message = try std.fmt.allocPrint(a, "expected ')' after \"...\", found \"{s}\"", .{next}) };
            if (!lex.eq(next, ",")) return .{ .message = try std.fmt.allocPrint(a, "expected ',' or ')', found \"{s}\"", .{next}) }; index += 1;
        };
        index += 1; params = list.items;
    }
    const m = try a.create(Macro); m.* = .{ .name = name, .parameters = params, .variadic = variadic, .replacement = try a.dupe(lex.Token, tokens[index..]), .position = position, .main = main };
    if (m.replacement.len > 0) { m.replacement[0].space = false; if (lex.eq(m.replacement[0].spelling, "##") or lex.eq(m.replacement[m.replacement.len - 1].spelling, "##")) return .{ .message = "'##' cannot appear at either end of a macro expansion" }; }
    for (m.replacement, 0..) |t, i| {
        if (t.kind == .identifier and lex.eq(t.spelling, "__VA_ARGS__") and !variadic) return .{ .message = va_error };
        if (params != null and lex.eq(t.spelling, "#") and (i + 1 == m.replacement.len or m.replacement[i + 1].kind != .identifier or m.parameter(m.replacement[i + 1].spelling) == null)) return .{ .message = "'#' is not followed by a macro parameter" };
    }
    return .{ .macro = m };
}
pub fn identical(a: *Macro, b: *Macro) bool {
    if ((a.parameters == null) != (b.parameters == null) or a.variadic != b.variadic or a.replacement.len != b.replacement.len) return false;
    if (a.parameters) |ps| { if (ps.len != b.parameters.?.len) return false; for (ps, b.parameters.?) |x, y| if (!lex.eq(x, y)) return false; }
    for (a.replacement, b.replacement) |x, y| if (!lex.eq(x.spelling, y.spelling) or x.space != y.space) return false; return true;
}

const std = @import("std");
const lex = @import("lexer.zig");
const defs = @import("definitions.zig");
fn contains(set: []const lex.Text, name: lex.Text) bool { for (set) |n| if (lex.eq(n, name)) return true; return false; }
fn unite(a: std.mem.Allocator, x: []const lex.Text, y: []const lex.Text) ![]const lex.Text { var names: std.ArrayList(lex.Text) = .empty; try names.appendSlice(a, x); for (y) |name| if (!contains(names.items, name)) { try names.append(a, name); }; return names.items; }
fn intersect(a: std.mem.Allocator, x: []const lex.Text, y: []const lex.Text) ![]const lex.Text { var names: std.ArrayList(lex.Text) = .empty; for (x) |name| if (contains(y, name)) { try names.append(a, name); }; return names.items; }
fn stringize(a: std.mem.Allocator, ts: []const lex.Token, space: bool) !lex.Token {
    var bytes: std.ArrayList(u8) = .empty; try bytes.append(a, '"');
    for (ts, 0..) |t, i| { if (i > 0 and t.space) try bytes.append(a, ' '); for (t.spelling) |c| { if ((t.kind == .string or t.kind == .character) and (c == '\\' or c == '"')) try bytes.append(a, '\\'); try bytes.append(a, c); } }
    try bytes.append(a, '"'); return .{ .kind = .string, .spelling = bytes.items, .space = space };
}
const Item = struct { paste: bool = false, tokens: []const lex.Token = &.{} };
pub fn expand(a: std.mem.Allocator, host: anytype, tokens: []const lex.Token, file: lex.Text, offset: i64) anyerror![]lex.Token {
    var input: std.ArrayList(lex.Token) = .empty; try input.appendSlice(a, tokens); var result: std.ArrayList(lex.Token) = .empty;
    while (input.items.len > 0) {
        const t = input.orderedRemove(0);
        if (t.kind != .identifier or contains(t.hide, t.spelling)) { try result.append(a, t); continue; }
        const pos: defs.Position = .{ .file = file, .line = t.line + offset };
        if (defs.builtin(t.spelling)) {
            var produced = t; produced.hide = &.{}; produced.kind = .number;
            if (lex.eq(t.spelling, "__COUNTER__")) { produced.spelling = try std.fmt.allocPrint(a, "{d}", .{host.builtins[0]}); host.builtins[0] += 1; }
            else if (lex.eq(t.spelling, "__FILE__")) { produced.kind = .string; produced.spelling = try std.fmt.allocPrint(a, "\"{s}\"", .{file}); host.builtins[1] += 1; }
            else { produced.spelling = try std.fmt.allocPrint(a, "{d}", .{pos.line}); host.builtins[2] += 1; }
            try result.append(a, produced); continue;
        }
        const macro = host.table.get(t.spelling) orelse { try result.append(a, t); continue; };
        var raw: std.ArrayList([]const lex.Token) = .empty; var hide = t.hide;
        if (macro.parameters) |ps| {
            if (input.items.len == 0 or !lex.eq(input.items[0].spelling, "(")) { try result.append(a, t); continue; }
            var depth: usize = 0; var first: usize = 1; var close: ?usize = null; var commas: std.ArrayList(lex.Token) = .empty;
            for (input.items[1..], 1..) |x, i| {
                if (lex.eq(x.spelling, ")") and depth == 0) { try raw.append(a, try a.dupe(lex.Token, input.items[first..i])); close = i; break; }
                if (lex.eq(x.spelling, ",") and depth == 0) { try raw.append(a, try a.dupe(lex.Token, input.items[first..i])); try commas.append(a, x); first = i + 1; }
                else if (lex.eq(x.spelling, "(")) depth += 1 else if (lex.eq(x.spelling, ")")) depth -= 1;
            }
            var message: ?lex.Text = null; const fixed = ps.len - @intFromBool(macro.variadic); const k = raw.items.len;
            if (close == null) message = try std.fmt.allocPrint(a, "unterminated argument list invoking macro \"{s}\"", .{macro.name})
            else if (ps.len == 0 and !(k == 1 and raw.items[0].len == 0)) message = try std.fmt.allocPrint(a, "macro \"{s}\" passed {d} arguments, but takes just 0", .{macro.name, k})
            else if (k < fixed) message = try std.fmt.allocPrint(a, "macro \"{s}\" requires {d} arguments, but only {d} given", .{macro.name, fixed, k})
            else if (k > fixed and !macro.variadic and ps.len != 0) message = try std.fmt.allocPrint(a, "macro \"{s}\" passed {d} arguments, but takes just {d}", .{macro.name, k, fixed});
            if (message) |msg| { try host.diag(pos, "error", msg); try result.append(a, t); continue; }
            hide = try intersect(a, hide, input.items[close.?].hide);
            if (macro.variadic) {
                var variable: std.ArrayList(lex.Token) = .empty;
                if (k > fixed) for (raw.items[fixed..], fixed..) |arg, i| { if (i > fixed) try variable.append(a, commas.items[i - 1]); try variable.appendSlice(a, arg); };
                raw.items.len = @min(fixed, raw.items.len); try raw.append(a, variable.items);
            }
            input.replaceRangeAssumeCapacity(0, close.? + 1, &.{});
        }
        hide = try unite(a, hide, &.{macro.name});
        const cache = try a.alloc(?[]lex.Token, if (macro.parameters) |ps| ps.len else 0); @memset(cache, null);
        var items: std.ArrayList(Item) = .empty; var i: usize = 0;
        while (i < macro.replacement.len) : (i += 1) {
            const x = macro.replacement[i];
            if (lex.eq(x.spelling, "##")) { try items.append(a, .{ .paste = true }); continue; }
            if (macro.parameters != null and lex.eq(x.spelling, "#")) {
                i += 1; const index = macro.parameter(macro.replacement[i].spelling).?; const value = try a.alloc(lex.Token, 1); value[0] = try stringize(a, raw.items[index], x.space); try items.append(a, .{ .tokens = value }); continue;
            }
            if (x.kind == .identifier) if (macro.parameter(x.spelling)) |index| {
                const pasted = (i > 0 and lex.eq(macro.replacement[i - 1].spelling, "##")) or (i + 1 < macro.replacement.len and lex.eq(macro.replacement[i + 1].spelling, "##"));
                var value: []lex.Token = undefined;
                if (pasted) value = try a.dupe(lex.Token, raw.items[index]) else { if (cache[index] == null) cache[index] = try expand(a, host, raw.items[index], file, offset); value = try a.dupe(lex.Token, cache[index].?); }
                if (value.len == 0) { value = try a.alloc(lex.Token, 1); value[0] = .{ .kind = .placemarker, .spelling = "", .space = x.space }; } else value[0].space = x.space;
                try items.append(a, .{ .tokens = value }); continue;
            };
            const value = try a.alloc(lex.Token, 1); value[0] = x; try items.append(a, .{ .tokens = value });
        }
        var substituted: std.ArrayList(lex.Token) = .empty; i = 0;
        while (i < items.items.len) : (i += 1) {
            const item = items.items[i]; if (!item.paste) { try substituted.appendSlice(a, item.tokens); continue; }
            const left = substituted.pop().?; i += 1; const next = items.items[i]; const fake = [_]lex.Token{.{ .kind = .punctuator, .spelling = "##" }}; const right = if (next.paste) fake[0..] else next.tokens; var r = right[0];
            if (left.kind == .placemarker) { r.space = left.space; try substituted.append(a, r); }
            else if (r.kind == .placemarker) try substituted.append(a, left)
            else { const joined = try std.mem.concat(a, u8, &.{left.spelling, r.spelling}); if (lex.single(joined)) |single| { var value = single; value.space = left.space; value.hide = try intersect(a, left.hide, r.hide); try substituted.append(a, value); }
                else { try host.diag(pos, "error", try std.fmt.allocPrint(a, "pasting \"{s}\" and \"{s}\" does not give a valid preprocessing token", .{left.spelling, r.spelling})); r.space = false; try substituted.append(a, left); try substituted.append(a, r); } }
            try substituted.appendSlice(a, right[1..]);
        }
        var cleaned: std.ArrayList(lex.Token) = .empty; var pending_space = false;
        for (substituted.items) |x| { if (x.kind == .placemarker) { pending_space = pending_space or x.space; continue; } var value = x; value.line = t.line; value.space = value.space or pending_space; pending_space = false; value.hide = try unite(a, value.hide, hide); try cleaned.append(a, value); }
        if (cleaned.items.len > 0) cleaned.items[0].space = t.space else if (t.space and input.items.len > 0) input.items[0].space = true;
        macro.expanded += 1; try input.insertSlice(a, 0, cleaned.items);
    }
    return result.items;
}

const std = @import("std");
const lex = @import("lexer.zig");
const defs = @import("definitions.zig");
const Node = struct { kind: enum { constant, identifier, unary, binary, conditional }, value: i64 = 0, text: lex.Text = "", left: ?*Node = null, right: ?*Node = null, third: ?*Node = null };
pub const Parser = struct {
    a: std.mem.Allocator, tokens: []const lex.Token, p: usize = 0, message: lex.Text = "",
    fn fail(p: *Parser, text: lex.Text) error{InvalidExpression} { p.message = text; return error.InvalidExpression; }
    fn peek(p: *Parser) lex.Text { return if (p.p < p.tokens.len) p.tokens[p.p].spelling else ""; }
    fn node(p: *Parser, n: Node) !*Node { const r = try p.a.create(Node); r.* = n; return r; }
    fn integer(p: *Parser, text: lex.Text) !i64 {
        var t = text; for ([_]lex.Text{"ll", "LL", "l", "L"}) |suffix| if (t.len > suffix.len and std.mem.endsWith(u8, t, suffix)) { t = t[0..t.len - suffix.len]; break; };
        var base: u8 = 10; if (std.mem.startsWith(u8, t, "0x") or std.mem.startsWith(u8, t, "0X")) { t = t[2..]; base = 16; } else if (t[0] == '0') base = 8;
        if (t.len > 0) { var valid = true; for (t) |c| { const digit = std.fmt.charToDigit(c, base) catch { valid = false; break; }; _ = digit; } if (valid) return std.fmt.parseInt(i64, t, base) catch unreachable; }
        return p.fail(try std.fmt.allocPrint(p.a, "invalid integer constant \"{s}\"", .{text}));
    }
    fn primary(p: *Parser) anyerror!*Node {
        if (p.p == p.tokens.len) return p.fail("expected value at end of expression"); const t = p.tokens[p.p]; p.p += 1;
        if (t.kind == .number) return p.node(.{ .kind = .constant, .value = try p.integer(t.spelling) });
        if (t.kind == .identifier) return p.node(.{ .kind = .identifier, .text = t.spelling });
        if (t.kind == .character) {
            const inside = t.spelling[1..t.spelling.len - 1]; var value: ?i64 = null;
            if (inside.len == 1 and inside[0] != '\\' and inside[0] != '\'') value = inside[0];
            if (inside.len == 2 and inside[0] == '\\') value = switch (inside[1]) { 'n' => 10, 't' => 9, '\\' => 92, '\'' => 39, '"' => 34, '0' => 0, else => null };
            return if (value) |v| p.node(.{ .kind = .constant, .value = v }) else p.fail(try std.fmt.allocPrint(p.a, "invalid character constant {s}", .{t.spelling}));
        }
        if (lex.eq(t.spelling, "(")) { const n = try p.expression(); if (!lex.eq(p.peek(), ")")) return p.fail("missing ')' in expression"); p.p += 1; return n; }
        return p.fail(try std.fmt.allocPrint(p.a, "expected value before \"{s}\"", .{t.spelling}));
    }
    fn unary(p: *Parser) anyerror!*Node { const op = p.peek(); if (lex.eq(op, "+") or lex.eq(op, "-") or lex.eq(op, "!") or lex.eq(op, "~")) { p.p += 1; return p.node(.{ .kind = .unary, .text = op, .left = try p.unary() }); } return p.primary(); }
    fn precedence(op: lex.Text) usize { const levels = [_]lex.Text{"||", "&&", "|", "^", "&", "== !=", "< > <= >=", "<< >>", "+ -", "* / %"}; for (levels, 1..) |ops, i| { var it = std.mem.splitScalar(u8, ops, ' '); while (it.next()) |s| if (lex.eq(s, op)) return i; } return 0; }
    fn binary(p: *Parser, minimum: usize) anyerror!*Node { var left = try p.unary(); while (precedence(p.peek()) >= minimum) { const op = p.peek(); const level = precedence(op); p.p += 1; left = try p.node(.{ .kind = .binary, .text = op, .left = left, .right = try p.binary(level + 1) }); } return left; }
    fn expression(p: *Parser) anyerror!*Node { var left = try p.binary(1); if (lex.eq(p.peek(), "?")) { p.p += 1; const yes = try p.expression(); if (!lex.eq(p.peek(), ":")) return p.fail("'?' without following ':'"); p.p += 1; left = try p.node(.{ .kind = .conditional, .left = left, .right = yes, .third = try p.expression() }); } return left; }
    pub fn parse(p: *Parser, directive: lex.Text) !*Node { if (p.tokens.len == 0) return p.fail(try std.fmt.allocPrint(p.a, "#{s} with no expression", .{directive})); const n = try p.expression(); if (p.p != p.tokens.len) return p.fail(try std.fmt.allocPrint(p.a, "missing binary operator before \"{s}\"", .{p.peek()})); return n; }
};
pub fn evaluate(n: *Node, host: anytype, pos: defs.Position) anyerror!?i64 {
    if (n.kind == .constant) return n.value;
    if (n.kind == .identifier) { try host.diag(pos, "warning", try std.fmt.allocPrint(host.a, "identifier \"{s}\" evaluates to 0", .{n.text})); return 0; }
    const a = (try evaluate(n.left.?, host, pos)) orelse return null;
    if (n.kind == .unary) return if (lex.eq(n.text, "+")) a else if (lex.eq(n.text, "-")) -a else if (lex.eq(n.text, "!")) @intFromBool(a == 0) else -a - 1;
    if (n.kind == .conditional) return evaluate(if (a != 0) n.right.? else n.third.?, host, pos);
    const op = n.text;
    if (lex.eq(op, "&&") and a == 0) return 0; if (lex.eq(op, "||") and a != 0) return 1;
    const b = (try evaluate(n.right.?, host, pos)) orelse return null;
    if (lex.eq(op, "&&") or lex.eq(op, "||")) return @intFromBool(b != 0);
    if ((lex.eq(op, "/") or lex.eq(op, "%")) and b == 0) { try host.diag(pos, "error", "division by zero in #if"); return null; }
    if (lex.eq(op, "+")) return a + b; if (lex.eq(op, "-")) return a - b; if (lex.eq(op, "*")) return a * b; if (lex.eq(op, "/")) return @divTrunc(a, b); if (lex.eq(op, "%")) return @rem(a, b);
    if (lex.eq(op, "<<")) return a << @intCast(b); if (lex.eq(op, ">>")) return a >> @intCast(b); if (lex.eq(op, "&")) return a & b; if (lex.eq(op, "|")) return a | b; if (lex.eq(op, "^")) return a ^ b;
    return @intFromBool(if (lex.eq(op, "==")) a == b else if (lex.eq(op, "!=")) a != b else if (lex.eq(op, "<")) a < b else if (lex.eq(op, ">")) a > b else if (lex.eq(op, "<=")) a <= b else a >= b);
}

const std = @import("std");
const lex = @import("lexer.zig");
pub const File = struct { path: lex.Text, document: lex.Document, guard: ?lex.Text, entered: usize = 0, skipped: usize = 0, once: bool = false, output_lines: usize = 0, skipped_lines: i64 = 0 };
pub const Manager = struct {
    a: std.mem.Allocator, io: std.Io, files: std.ArrayList(*File) = .empty, order: std.ArrayList(*File) = .empty,
    pub fn get(m: *Manager, path: lex.Text) !?*File {
        for (m.files.items) |f| if (lex.eq(f.path, path)) return f;
        const source = std.Io.Dir.cwd().readFileAlloc(m.io, try std.fmt.allocPrint(m.a, "input/{s}", .{path}), m.a, .unlimited) catch |err| switch (err) { error.FileNotFound => return null, else => return err };
        const f = try m.a.create(File); f.* = .{ .path = path, .document = try lex.lex(m.a, source), .guard = null }; f.guard = guard(f.document); try m.files.append(m.a, f); return f;
    }
    pub fn search(m: *Manager, name: lex.Text, quoted: bool) !?*File { if (quoted) if (try m.get(name)) |f| return f; return m.get(try std.fmt.allocPrint(m.a, "include/{s}", .{name})); }
    pub fn enter(m: *Manager, f: *File) !void { if (f.entered == 0) try m.order.append(m.a, f); f.entered += 1; }
};
fn guard(d: lex.Document) ?lex.Text {
    var first: ?[]const lex.Token = null; var last: []const lex.Token = &.{}; var depth: i64 = 0; var ended = false;
    for (d.lines) |line| {
        const ts = line.tokens; if (ts.len == 0) continue;
        if (ended) return null; if (first == null) { if (ts.len != 3 or !lex.eq(ts[0].spelling, "#") or !lex.eq(ts[1].spelling, "ifndef") or ts[2].kind != .identifier) return null; first = ts; }
        last = ts;
        if (ts.len >= 2 and lex.eq(ts[0].spelling, "#")) { const k = ts[1].spelling;
            if (lex.eq(k, "if") or lex.eq(k, "ifdef") or lex.eq(k, "ifndef")) depth += 1
            else if (lex.eq(k, "endif")) { depth -= 1; if (depth == 0) ended = true; }
            else if (depth == 1 and (lex.eq(k, "else") or std.mem.startsWith(u8, k, "elif"))) return null;
        }
    }
    if (first == null or !ended or last.len != 2 or !lex.eq(last[1].spelling, "endif")) return null; return first.?[2].spelling;
}

const std = @import("std");
pub const Text = []const u8;
pub fn eq(a: Text, b: Text) bool { return std.mem.eql(u8, a, b); }
pub const Kind = enum { identifier, number, character, string, header, punctuator, other, placemarker };
pub const Token = struct { spelling: Text, kind: Kind, line: i64 = 1, space: bool = false, hide: []const Text = &.{} };
pub const Line = struct { tokens: []Token, start: i64, end: i64 };
pub const Document = struct { lines: []const Line, physical: i64 };
pub fn one(text: Text) Token {
    const c = text[0]; var end: usize = 1; var kind: Kind = .other;
    if (std.ascii.isAlphabetic(c) or c == '_') { kind = .identifier; while (end < text.len and (std.ascii.isAlphanumeric(text[end]) or text[end] == '_')) end += 1; }
    else if (std.ascii.isDigit(c) or (c == '.' and text.len > 1 and std.ascii.isDigit(text[1]))) {
        kind = .number; while (end < text.len) { const x = text[end]; if (std.mem.indexOfScalar(u8, "eEpP", x) != null and end + 1 < text.len and (text[end + 1] == '+' or text[end + 1] == '-')) end += 2 else if (std.ascii.isAlphanumeric(x) or x == '_' or x == '.') end += 1 else break; }
